    setIdea: (key: keyof MeshIdeaFlags, value: number) => {
      state.ideas = { ...state.ideas, [key]: value };
    },
    setIdeas: (flags: MeshIdeaFlags) => {
      state.ideas = { ...flags };
    },
    setTextureSource: (src: TexImageSource | null) => {
      state.textureSource = src;
    },
    setUseTexture: (on: number) => {
      state.useTexture = on;
    },
    setRefractStrength: (v: number) => {
      state.refractStrength = v;
    },
    getProgress: () => state.progress,
    getAlpha: () => state.alpha,
    destroy: () => {
      gl.deleteProgram(prog);
      gl.deleteBuffer(posBuf);
      gl.deleteBuffer(uvBuf);
      gl.deleteBuffer(idxBuf);
      if (tex) gl.deleteTexture(tex);
      gl.deleteShader(vs);
      gl.deleteShader(fs);
    }
  };
}

