      opts.onComplete?.();
    }
  })().catch((error) => {
    console.error("[glimm] masked sweep failed:", error);
    cancel();
  }).finally(() => {
    resolveMidpoint();
    resolveDone();
  });
  return { midpoint, done, cancel, interrupt: cancel };
}

